import type { ViewerPluginCreator } from './../ricos-types/index.js';

import { DEFAULTS } from './defaults.js';
import type { VerticalEmbedPluginViewerConfig } from './types.js';
import { VERTICAL_EMBED_TYPE } from './types.js';
import { nodeViewRenderers } from './viewer/node-view-renderers.js';

export const pluginVerticalEmbed: ViewerPluginCreator<VerticalEmbedPluginViewerConfig> = config => {
  return {
    config: { ...DEFAULTS.config, ...config },
    type: VERTICAL_EMBED_TYPE,
    nodeViewRenderers,
  };
};
