import type { AppEmbedData_AppType } from './../ricos-schema/legacy/wix/rich_content/v1/index.js';

export const VERTICAL_EMBED_TYPE = 'wix-draft-plugin-vertical-embed';

export type EmbedItem = {
  id: string;
  name: string;
  pageUrl: string;
  imageSrc: string;
  imageWidth: number;
  imageHeight: number;
  description: string;
  scheduling: string;
  location: string;
  thumbnail: string;
  html: string;
  durations?: number;
};

export type ItemType = 'UNKNOWN_ITEM_TYPE' | 'BOOKING' | 'EVENT' | 'PRODUCT';

export type Image = {
  id?: string;
  url?: string;
  width?: number;
  height?: number;
  altText?: string;
};

export type PricingData = {
  minValue?: string;
  maxValue?: string;
  discountedValue?: string;
  currency?: string;
  pricingPlanId?: string;
};

export type EventDetails = {
  formattedDateAndTime?: string;
  startDate?: string; // ISO timestamp
  endDate?: string; // ISO timestamp
  timeZoneId?: string;
  location?: string;
};

export type BookingDetails = {
  durations?: number[];
};

export type EmbeddableItem = {
  id?: string;
  title: string;
  image?: Image;
  pageUrl: string;
  pricingData?: PricingData;
  itemType: ItemType;
  bookingDetails?: BookingDetails;
  eventDetails?: EventDetails;
};

export type GetEmbeddableItemResponse = {
  embeddableItem: EmbeddableItem;
};

export type ListEmbeddableItemsRequest = {
  itemType: ItemType;
  query?: string;
  limit?: number;
  cursor?: string;
};

export type ListEmbeddableItemsResponse = {
  items: EmbeddableItem[];
  nextCursor?: string;
  prevCursor?: string;
};

export type VerticalApiType = Lowercase<
  Exclude<AppEmbedData_AppType, AppEmbedData_AppType.UNRECOGNIZED>
>;

export type VerticalEmbedErrorType = 'NOT_FOUND' | 'FAILED';

export type VerticalEmbedPluginEditorConfig = {
  type: 'verticalEmbed';
  exposeEmbedButtons?: string[];
  slimLayout?: boolean;
  // this should be removed once we have a unified way to pass action colors to Ricos
  colors?: Record<string, string>;
};

export type VerticalEmbedPluginViewerConfig = {
  changeBaseUrl?: (url: string) => string;
  slimLayout?: boolean;
  // this should be removed once we have a unified way to pass action colors to Ricos
  colors?: {
    titleColor?: string;
    textColor?: string;
    backgroundColor?: string;
    borderColor?: string;
    buttonFillColor?: string;
    buttonTextColor?: string;
    buttonBorderColor?: string;
    buttonFillColorHover?: string;
    buttonTextColorHover?: string;
    buttonBorderColorHover?: string;
    ribbonFillColor?: string;
    ribbonTextColor?: string;
    ribbonBorderColor?: string;
    imageBorderColor?: string;
  };
};
