import classNames from 'classnames';
import React from 'react';

import styles from './Ribbon-scss.js';

type RibbonProps = {
  children: React.ReactNode;
  className?: string;
};

export const Ribbon: React.FC<RibbonProps> = ({ children, className }) => {
  return (
    <div className={classNames(styles.ribbon, className)}>
      <span className={styles.ribbonText}>{children}</span>
    </div>
  );
};
