import { sdk } from '@wix/image-kit';
import { useEffect, useMemo, useRef, useState } from 'react';

import { observeElementSize } from './../../_shared/observe-element-size.js';
import { getMediaId } from './../../wix-rich-content-common/lib/image-utils.js';

const WIX_STATIC_MEDIA_PREFIX = 'https://static.wixstatic.com/media';
const RESIZE_DEBOUNCE_MS = 300;
const SSR_FALLBACK_SIZE = 600;
const SSR_FALLBACK_QUALITY = 80;
const CLIENT_QUALITY = 100;

type ImageSource = {
  src: { url?: string; id?: string };
  width?: number;
  height?: number;
};

export const useBackgroundImageUrl = (
  image: ImageSource | undefined
): {
  containerRef: React.RefObject<HTMLDivElement>;
  backgroundImageUrl: string | undefined;
} => {
  const [dimensions, setDimensions] = useState<{ width: number; height: number } | null>(null);
  const [loadedUrl, setLoadedUrl] = useState<string | undefined>(() => getInitialUrl(image));
  const containerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const element = containerRef.current;
    if (!element) {
      return;
    }

    return observeElementSize(
      element,
      ({ width, height }) =>
        setDimensions(prev =>
          prev && prev.width === Math.ceil(width) && prev.height === Math.ceil(height)
            ? prev
            : { width: Math.ceil(width), height: Math.ceil(height) }
        ),
      { debounceMs: RESIZE_DEBOUNCE_MS }
    );
  }, []);

  const mediaId = useMemo(() => resolveMediaId(image), [image?.src?.id, image?.src?.url]);

  useEffect(() => {
    if (!image?.src?.url && !mediaId) {
      setLoadedUrl(undefined);
      return;
    }

    if (!mediaId) {
      setLoadedUrl(image?.src?.url);
      return;
    }

    if (!dimensions || dimensions.width === 0 || dimensions.height === 0) {
      setLoadedUrl(getSsrFallbackUrl(mediaId, image!));
      return;
    }

    const dpr = Math.min(typeof window !== 'undefined' ? window.devicePixelRatio || 1 : 1, 2);
    const targetUrl = getResizedUrl(
      mediaId,
      image!,
      Math.ceil(dimensions.width * dpr),
      Math.ceil(dimensions.height * dpr),
      CLIENT_QUALITY
    );
    if (!targetUrl) {
      setLoadedUrl(image?.src?.url);
      return;
    }

    let cancelled = false;
    prefetchImage(targetUrl).then(
      url => {
        if (!cancelled) {
          setLoadedUrl(url);
        }
      },
      () => {
        if (!cancelled) {
          setLoadedUrl(image?.src?.url);
        }
      }
    );
    return () => {
      cancelled = true;
    };
  }, [mediaId, dimensions, image?.src?.url, image?.width, image?.height]);

  return { containerRef, backgroundImageUrl: loadedUrl };
};

export const resolveMediaId = (image: ImageSource | undefined): string | undefined => {
  if (!image) {
    return undefined;
  }
  if (image.src.id) {
    return image.src.id;
  }
  if (image.src.url?.startsWith(WIX_STATIC_MEDIA_PREFIX)) {
    return getMediaId(image.src.url);
  }
  return undefined;
};

const getResizedUrl = (
  mediaId: string,
  image: ImageSource,
  width: number,
  height: number,
  quality: number
): string | undefined => {
  try {
    return sdk.getScaleToFillImageURL(
      mediaId,
      image.width ?? width,
      image.height ?? height,
      width,
      height,
      { quality }
    );
  } catch {
    return image.src?.url;
  }
};

const getSsrFallbackUrl = (mediaId: string, image: ImageSource): string | undefined =>
  getResizedUrl(mediaId, image, SSR_FALLBACK_SIZE, SSR_FALLBACK_SIZE, SSR_FALLBACK_QUALITY);

const prefetchImage = (url: string): Promise<string> =>
  new Promise((resolve, reject) => {
    const img = new Image();
    img.onload = () => resolve(url);
    img.onerror = reject;
    img.src = url;
  });

const getInitialUrl = (image: ImageSource | undefined): string | undefined => {
  if (!image) {
    return undefined;
  }
  const mediaId = resolveMediaId(image);
  if (mediaId) {
    return getSsrFallbackUrl(mediaId, image);
  }
  return image.src?.url;
};
