import React, { useContext } from 'react';

import { RicosViewerContext } from './../../ricos-context/index.js';
import type { AppEmbedData } from './../../ricos-schema/next-schema/index.js';
import type { NodeViewRendererProps } from './../../ricos-types/index.js';

import { VERTICAL_EMBED_TYPE } from '../types.js';
import { VerticalEmbedViewer } from './vertical-embed-viewer.js';

const VerticalEmbed = ({ node, nodeIndex, NodeViewContainer }: NodeViewRendererProps) => {
  const { helpers, config } = useContext(RicosViewerContext);
  return (
    <NodeViewContainer node={node} nodeIndex={nodeIndex}>
      <VerticalEmbedViewer
        nodeId={node.id}
        settings={config[VERTICAL_EMBED_TYPE] || {}}
        componentData={node.appEmbedData as AppEmbedData}
        helpers={helpers}
      />
    </NodeViewContainer>
  );
};

export default VerticalEmbed;
