import React from 'react';

import type { AppEmbedData } from './../../ricos-schema/next-schema/index.js';
import {
  AppEmbedData_ImageStyles_Position,
  AppEmbedData_RibbonStyles_Placement,
} from './../../ricos-schema/next-schema/generated/ricos_document.js';

import { MAX_RIBBON_TEXT_LENGTH } from '../constants.js';
import {
  generateContainerClassName,
  generateContentClasses,
  generateImageContainerProps,
} from '../viewer/vertical-embed-styles.js';
import { CardContent } from './card-content.js';
import contentStyles from './card-content-scss.js';
import styles from './card-scss.js';
import { Ribbon } from './ribbon.js';
import { useBackgroundImageUrl } from './use-background-image-url.js';

type CardProps = {
  title: string;
  buttonText: string;
  direction: 'ltr' | 'rtl';
  url: string;
  image?: { width?: number; height?: number; src: { url?: string; id?: string } };
  componentData: AppEmbedData;
  ribbonText?: string;
};

export const Card: React.FC<CardProps> = props => {
  const { title, buttonText, direction, image, componentData, ribbonText } = props;

  const imageStyles = componentData?.imageStyles || {};
  const shouldShowImage = !componentData?.hideImage && (image?.src?.url || image?.src?.id);
  const ribbonPlacement =
    componentData?.ribbonStyles?.ribbonPlacement ||
    AppEmbedData_RibbonStyles_Placement.PRODUCT_INFO;
  const shouldShowRibbon = !(componentData?.hideRibbon ?? true) && ribbonText;
  const { containerRef, backgroundImageUrl } = useBackgroundImageUrl(image);
  const imageContainerProps = generateImageContainerProps(imageStyles, styles);

  return (
    <div
      style={{ direction: direction as 'rtl' | 'ltr' }}
      className={generateContainerClassName(direction, imageStyles, styles)}
    >
      {shouldShowImage && (
        <div className={styles.imageContainer}>
          {/* div with background-image for better layout (aspect ratio, resizing) control, role="img" for accessibility */}
          <div
            ref={containerRef}
            className={imageContainerProps.className}
            style={{
              ...imageContainerProps.style,
              backgroundImage: backgroundImageUrl ? `url(${backgroundImageUrl})` : undefined,
            }}
            role="img"
            aria-label={title}
          />
          {shouldShowRibbon && ribbonPlacement === AppEmbedData_RibbonStyles_Placement.IMAGE && (
            <div className={styles.imageRibbon}>
              <Ribbon>{truncateRibbonText(ribbonText || '')}</Ribbon>
            </div>
          )}
        </div>
      )}
      <CardContent
        title={title}
        buttonText={buttonText}
        componentData={componentData}
        imagePosition={imageStyles.imagePosition || AppEmbedData_ImageStyles_Position.START}
        contentClasses={generateContentClasses(
          componentData?.cardStyles,
          imageStyles.imagePosition || AppEmbedData_ImageStyles_Position.START,
          contentStyles
        )}
        ribbonText={ribbonText}
        ribbonPlacement={ribbonPlacement}
      />
    </div>
  );
};

const truncateRibbonText = (text: string): string => {
  return text.length <= MAX_RIBBON_TEXT_LENGTH
    ? text
    : `${text.substring(0, MAX_RIBBON_TEXT_LENGTH)}...`;
};
